'use strict';
const input=$input.first()?.json||{};const t=v=>String(v??'').normalize('NFKC').trim();const storage=t(input.storageUsername).toLowerCase();const actor=t(input.telegramActorId||input.telegramUserId);
if(!/^actor_[a-f0-9]{32}$/.test(storage)||!/^tgactor_[a-f0-9]{64}$/.test(t(input.principalKey))||!/^[0-9a-f]{8}-[0-9a-f]{4}-5[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(t(input.principalUuid))||!/^\d+$/.test(actor))throw new Error('folder_immutable_identity_required');
const expected={userId:storage,memoryUserId:storage,tenantId:`tenant_${storage}`,memoryTenantId:`tenant_${storage}`,qdrantCollection:`kb_tenant_${storage}`,soulId:`chelsea_soul_${storage}`};for(const [k,v] of Object.entries(expected))if(t(input[k])!==v)throw new Error(`folder_identity_scope_mismatch:${k}`);
const root=t($env.CHELSEA_USER_FILES_ROOT||'/files/chelsea').replace(/\/+$/,'');if(!root.startsWith('/')||root==='/'||root==='/files'||root.includes('..'))throw new Error('folder_unsafe_root');const folderRoot=`${root}/${expected.tenantId}`;if(t(input.telegramActorId)&&t(input.telegramUserId)&&t(input.telegramActorId)!==t(input.telegramUserId))throw new Error('folder_telegram_actor_mismatch');return [{json:{...input,...expected,telegramActorId:actor,telegramUserId:actor,currentUsername:t(input.currentUsername).replace(/^@+/,''),filesRoot:root,folderRoot}}];

