=set -euo pipefail
root={{ JSON.stringify($json.filesRoot) }}
storage={{ JSON.stringify($json.storageUsername) }}
target={{ JSON.stringify($json.folderRoot) }}
case "$storage" in (actor_[0-9a-f][0-9a-f]*) ;; (*) echo 'invalid immutable storage key' >&2; exit 64;; esac
case "$target" in ("$root"/tenant_actor_*) ;; (*) echo 'path escape blocked' >&2; exit 65;; esac
install -d -m 0700 -- "$target" "$target/obsidian" "$target/exports" "$target/tmp"
for d in "$target" "$target/obsidian" "$target/exports" "$target/tmp"; do test -d "$d"; test "$(stat -c '%a' -- "$d")" = '700'; done
printf '{"folderRoot":"%s","verified":true,"mode":"700","directories":4}
' "$target
